# Spell proper names for clear, consistent Russian narration; on-screen names remain original.
PRON={'OpenAI':'Опен Эй Ай','Moonshot':'Муншот','Anthropic':'Антропик','Reuters':'Рейтер','Reddit':'Реддит','METR':'Метр','Redwood Research':'Редвуд Рисёрч','Pitchfork':'Питчфорк'}
